def find_Nth_Digit(n,m,x): 
    if (n == 1): 
        return x % 10
    y = m // 10
    z = m % 10
    if (z == 0): 
        return find_Nth_Digit(n - 1, m // 10, x) 
    if (x >= y * 10): 
        return find_Nth_Digit(n - 1, m // 10, (x - y * 10) / 10) 
    return (find_Nth_Digit(n - 1, m // 10, x) + (x - y * 10) * 10) % 10
```

