def comb_sort(arr):
    n = len(arr)
    gap = n
    while gap > 0:
        gap = int(gap / 1.2)
        for i in range(0, n - gap):
            j = i + gap
            while j < n and arr[j] > arr[j + gap]:
                arr[j], arr[j + gap] = arr[j + gap], arr[j]
    return arr
