        divisors = [1] 
        for i in range(2,int(x**0.5)+1): 
            if (x % i == 0): 
                divisors.append(i) 
                if (x // i != i): 
                    divisors.append(x//i) 
        return sum(divisors) 
    amicable_sum = 0
    for i in range(1,n+1): 
