def max_path_sum(triangle, m, n):
    for i in range(m - 2, -1, -1):
        for j in range(n):
            temp = triangle[i][j]
            if j > 0:
                temp = temp + triangle[i + 1][j - 1]
            if j < n - 1:
                temp = temp + triangle[i + 1][j]
            triangle[i][j] = temp
    return triangle[0][0]
