def max_sum_rectangular_grid(grid, n): 
    dp = [[0 for i in range(n)] for j in range(n)] 
    for i in range(n): 
        dp[i][i] = grid[i][i] 
    for L in range(2, n + 1): 
        for i in range(n - L + 1): 
            j = i + L - 1
            dp[i][j] = grid[i][j] 
            for k in range(i, j): 
                dp[i][j] = max(dp[i][j], 
                              dp[k + 1][j] + 
                              dp[i][k] + 
                              grid[k][j]) 
    return dp[0][n - 1]
```

