def is_subset_sum(arr, n, sum):
    dp = [[False for i in range(sum + 1)] for j in range(n + 1)]
    for i in range(0, n + 1):
        dp[i][0] = True
    for i in range(1, n + 1):
        for j in range(1, sum + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][sum]
```

