import math
def binomial_probability(n, k, p):
    if (k < 0 or k > n):
        return 0
    if (k == 0 or k == n):
        return math.pow(p, n)
    numerator = math.factorial(n)
    denominator = math.factorial(k) * math.factorial(n - k)
    return numerator / denominator
