def no_of_subsequences(arr,n): 
    dp = [0]*(n+1) 
    dp[0] = 1
    for i in range(1,n): 
        for j in range(i): 
            if (arr[i] > arr[j] * dp[i-j]): 
                dp[i] += dp[j] 
    return dp[n]
